-- 11-aliases-and-preferences. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- Reviewed snapshot import.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_11;
CREATE TEMP TABLE afl_remaining_11_0 AS SELECT id, player_id, alias, normalized_alias, source FROM player_aliases WHERE 0;
CREATE TEMP TABLE afl_remaining_11_1 AS SELECT key, value_json FROM app_preferences WHERE 0;
CREATE TEMP TABLE afl_remaining_11_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_11_check BEFORE INSERT ON afl_remaining_11_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_11_0 i JOIN player_aliases t ON t.id=i.id WHERE t.player_id IS NOT i.player_id OR t.alias IS NOT i.alias OR t.normalized_alias IS NOT i.normalized_alias OR t.source IS NOT i.source) THEN RAISE(ROLLBACK,'player_aliases: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_11_0 i JOIN player_aliases t ON t.player_id=i.player_id AND t.normalized_alias=i.normalized_alias WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'player_aliases: natural key uses another ID.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_11_1 i JOIN app_preferences t ON t.key=i.key WHERE t.value_json IS NOT i.value_json) THEN RAISE(ROLLBACK,'app_preferences: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_11_1 i JOIN app_preferences t ON t.key=i.key WHERE NOT (t.key=i.key)) THEN RAISE(ROLLBACK,'app_preferences: natural key uses another ID.') END;
END;
DROP TRIGGER afl_remaining_11_check;
DROP TABLE afl_remaining_11_guard;
DROP TABLE afl_remaining_11_0;
DROP TABLE afl_remaining_11_1;
RELEASE SAVEPOINT afl_remaining_11;
PRAGMA foreign_key_check;
SELECT 'player_aliases' AS imported_table,count(*) AS reviewed_records_present FROM player_aliases t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='80503c36-3209-540b-afa3-ca99409ededf' AND m.target_table='player_aliases' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'app_preferences' AS imported_table,count(*) AS reviewed_records_present FROM app_preferences t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='80503c36-3209-540b-afa3-ca99409ededf' AND m.target_table='app_preferences' AND m.target_id=CAST(t.key AS TEXT));
